sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (!newValue) {
        g_form.setValue('under_18', 'false');
        return;
    }

    var birthDate = new Date(newValue);
    var today = new Date();
    var age = today.getFullYear() - birthDate.getFullYear();
    var monthDiff = today.getMonth() - birthDate.getMonth();

    // Adjusting age if the birth month/day hasn't occurred yet in this year.
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
        age--;
    }

    // Set flag true if under 18, else false
    if (age < 18) {
        g_form.setValue('under_18', 'true');
    } else {
        g_form.setValue('under_18', 'false');
    }
}
